import fs from 'node:fs';
import assert from 'node:assert/strict';

const path = 'public/content/angular-senior.json';
const track = JSON.parse(fs.readFileSync(path, 'utf8'));
assert.equal(track.topics.flatMap((topic) => topic.questions).length, 108, 'Expansion must run once from the reviewed 108-question baseline.');

const S = {
  html: { title: 'MDN · HTML', url: 'https://developer.mozilla.org/en-US/docs/Web/HTML' },
  css: { title: 'MDN · CSS', url: 'https://developer.mozilla.org/en-US/docs/Web/CSS' },
  a11y: { title: 'W3C · WCAG 2.2', url: 'https://www.w3.org/TR/WCAG22/' },
  perf: { title: 'web.dev · Performance', url: 'https://web.dev/learn/performance/' },
  js: { title: 'MDN · JavaScript', url: 'https://developer.mozilla.org/en-US/docs/Web/JavaScript' },
  event: { title: 'MDN · Execution model', url: 'https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Execution_model' },
  modules: { title: 'MDN · JavaScript modules', url: 'https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Modules' },
  ts: { title: 'TypeScript Handbook', url: 'https://www.typescriptlang.org/docs/handbook/' },
  tsTypes: { title: 'TypeScript · Creating types from types', url: 'https://www.typescriptlang.org/docs/handbook/2/types-from-types.html' },
  patterns: { title: 'Refactoring Guru · Design patterns', url: 'https://refactoring.guru/design-patterns' },
  http: { title: 'MDN · HTTP', url: 'https://developer.mozilla.org/en-US/docs/Web/HTTP' },
  security: { title: 'OWASP · Web Security Testing Guide', url: 'https://owasp.org/www-project-web-security-testing-guide/' },
  securityHeaders: { title: 'web.dev · Security headers', url: 'https://web.dev/articles/security-headers' },
  angular: { title: 'Angular documentation', url: 'https://angular.dev/overview' },
  angularRoadmap: { title: 'Angular roadmap', url: 'https://angular.dev/roadmap' },
  rxjs: { title: 'RxJS documentation', url: 'https://rxjs.dev/guide/overview' },
  ngrx: { title: 'NgRx documentation', url: 'https://ngrx.io/guide/store' },
  testing: { title: 'Angular · Testing', url: 'https://angular.dev/guide/testing' },
  vitest: { title: 'Vitest documentation', url: 'https://vitest.dev/guide/' },
};
const p = (text) => `<p>${text}</p>`;
const q = (en, ar, answerEn, answerAr, sources, extra = {}) => ({
  prompt: { en, ar }, answer: { en: p(answerEn), ar: p(answerAr) }, codeHtml: '', kind: 'discussion',
  review: { status: 'reviewed', lastReviewedAt: '2026-09-16', versionNotes: 'Senior frontend expansion · checked against linked official documentation.', sources: sources.map((key) => S[key]) },
  ...extra,
});
const additions = {
  'topic-1': [
    q('How does the CSS cascade choose a winning declaration?', 'كيف تختار CSS الـdeclaration الفائزة في الـcascade؟', 'I compare origin and importance, cascade layer, specificity, scoping proximity, then source order. I use layers and low-specificity selectors to make the result predictable instead of escalating with <code>!important</code>.', 'أقارن origin وimportance ثم cascade layer وspecificity وscoping proximity وأخيرًا ترتيب المصدر. أستخدم layers وselectors قليلة specificity بدل الدخول في حرب <code>!important</code>.', ['css']),
    q('What problem do CSS cascade layers solve?', 'ما المشكلة التي تحلها CSS cascade layers؟', '<code>@layer</code> defines an explicit priority between groups such as reset, vendor, components, and utilities. Unlayered author styles outrank layered normal styles, so the layer order must be designed deliberately.', '<code>@layer</code> يحدد أولوية واضحة بين reset وvendor وcomponents وutilities. الـauthor styles غير الموجودة داخل layer تتغلب عادة على layered normal styles، لذلك يجب تصميم الترتيب بوضوح.', ['css']),
    q('When do container queries beat viewport media queries?', 'متى تكون container queries أنسب من viewport media queries؟', 'A reusable component should respond to the space its container provides, not the entire viewport. I use media queries for page-level conditions and container queries for component-level layout changes.', 'الـcomponent القابل لإعادة الاستخدام يجب أن يستجيب لمساحة الـcontainer وليس عرض الشاشة كله. أستخدم media queries لتخطيط الصفحة وcontainer queries لتغيرات الـcomponent.', ['css']),
    q('Explain intrinsic sizing: min-content, max-content, and fit-content.', 'اشرح intrinsic sizing: ‏min-content وmax-content وfit-content.', '<code>min-content</code> is the smallest size without avoidable overflow, <code>max-content</code> is the ideal unwrapped size, and <code>fit-content</code> clamps an intrinsic size to available space. They help build resilient layouts without hard-coded widths.', '<code>min-content</code> أصغر حجم ممكن دون overflow يمكن تجنبه، و<code>max-content</code> الحجم المثالي بلا wrapping، و<code>fit-content</code> يقيّد الحجم بالمساحة المتاحة. تفيد في layouts مرنة دون أرقام ثابتة.', ['css']),
    q('How do stacking contexts cause unexpected z-index bugs?', 'كيف تسبب stacking contexts مشاكل غير متوقعة في z-index؟', 'A child cannot escape its parent stacking context even with a huge z-index. I inspect context creators such as positioned elements with z-index, transforms, opacity, isolation, and top-layer elements before changing numbers.', 'الـchild لا يستطيع الخروج من stacking context الأب حتى بقيمة z-index ضخمة. أفحص أسباب إنشاء context مثل position مع z-index وtransform وopacity وisolation وعناصر top layer قبل تغيير الأرقام.', ['css']),
    q('What are subgrid and grid auto-placement useful for?', 'فيم تستخدم subgrid وgrid auto-placement؟', 'Subgrid lets nested content align to parent tracks; auto-placement fills items according to the grid algorithm. I use them for consistent card internals and data layouts, while checking source order remains logical for accessibility.', 'تسمح subgrid للمحتوى الداخلي بمحاذاة tracks الخاصة بالأب، ويملأ auto-placement العناصر حسب خوارزمية grid. أستخدمهما لاتساق البطاقات مع الحفاظ على source order منطقي للـaccessibility.', ['css', 'a11y']),
    q('How do you design motion that respects user preferences?', 'كيف تصمم الحركة مع احترام تفضيلات المستخدم؟', 'I use motion to explain state changes, keep it short, animate compositor-friendly properties when possible, and provide a <code>prefers-reduced-motion</code> path that removes nonessential movement.', 'أستخدم الحركة لتوضيح تغير الحالة، وأجعلها قصيرة، وأحرك خصائص مناسبة للـcompositor قدر الإمكان، وأوفر مسار <code>prefers-reduced-motion</code> يلغي الحركة غير الضرورية.', ['css', 'a11y']),
    q('What makes a robust design-token system?', 'ما الذي يجعل design-token system قويًا؟', 'Tokens represent semantic decisions such as surface, text, spacing, and focus rather than raw component values. I separate primitive and semantic tokens, support themes through variables, document ownership, and test contrast.', 'الـtokens تمثل قرارات semantic مثل surface وtext وspacing وfocus بدل قيم component خام. أفصل primitive عن semantic tokens، وأدعم themes بالـvariables، وأوثق الملكية وأختبر contrast.', ['css', 'a11y']),
    q('How do you avoid layout shift caused by fonts?', 'كيف تتجنب layout shift الناتج عن الخطوط؟', 'I subset and preload only critical fonts, use an appropriate display strategy, provide metric-compatible fallbacks with size-adjust when needed, and measure CLS rather than assuming a font optimization helped.', 'أقسّم الخط وأحمّل الخط الضروري مبكرًا فقط، وأختار font-display مناسبًا، وأستخدم fallback متوافق المقاييس وsize-adjust عند الحاجة، ثم أقيس CLS.', ['css', 'perf']),
    q('How would you audit RTL beyond flipping the layout?', 'كيف تراجع RTL أبعد من مجرد قلب الـlayout؟', 'I verify logical spacing, start/end alignment, icons with directional meaning, mixed bidi text, form controls, charts, keyboard order, truncation, and screenshots in both directions. Some icons mirror; neutral symbols do not.', 'أراجع logical spacing وstart/end والأيقونات ذات الاتجاه والنص المختلط والنماذج والرسوم وترتيب الكيبورد والـtruncation وscreenshots في الاتجاهين. بعض الأيقونات تُعكس وبعضها لا.', ['css', 'a11y']),
  ],
  'topic-13': [
    q('What is the accessibility tree, and how can CSS affect it?', 'ما هي accessibility tree وكيف يمكن أن تؤثر CSS عليها؟', 'Assistive technology consumes a semantic tree derived from DOM, roles, names, states, and browser rules. Hiding content with <code>display:none</code> or <code>hidden</code> removes it from that tree, while visually-hidden techniques can keep meaningful text available.', 'تقنيات المساعدة تستخدم شجرة semantic مشتقة من DOM والroles والأسماء والحالات. إخفاء المحتوى بـ<code>display:none</code> أو <code>hidden</code> يزيله منها، بينما visually-hidden قد يبقي النص متاحًا.', ['html', 'a11y']),
    q('How do accessible name and description computation work?', 'كيف يتم حساب accessible name وdescription؟', 'A control name can come from visible text, an associated label, <code>aria-labelledby</code>, or <code>aria-label</code> with defined precedence. I prefer visible native labels and use descriptions for supporting help, not as a replacement for the name.', 'قد يأتي اسم العنصر من النص المرئي أو label أو <code>aria-labelledby</code> أو <code>aria-label</code> حسب أولوية محددة. أفضل label مرئي وأستخدم description للمساعدة الإضافية لا كبديل للاسم.', ['a11y']),
    q('When should focus move after a UI update?', 'متى يجب نقل focus بعد تحديث الواجهة؟', 'I move focus when context changes and the user would otherwise be lost, such as opening a modal or removing the focused item. I avoid stealing focus after routine updates and return it to a sensible trigger when a modal closes.', 'أنقل focus عندما يتغير السياق وقد يضيع المستخدم، مثل فتح modal أو حذف العنصر المحدد. لا أسرق focus بعد تحديث عادي وأعيده لمكان منطقي عند غلق modal.', ['a11y']),
    q('How do live regions differ from moving focus?', 'ما الفرق بين live regions ونقل focus؟', 'A live region announces an asynchronous status without changing the user’s position. Focus movement changes navigation context. I use polite announcements for nonurgent updates, assertive sparingly, and avoid repeatedly announcing noisy content.', 'تعلن live region حالة غير متزامنة دون تغيير مكان المستخدم، بينما نقل focus يغير سياق التنقل. أستخدم polite للتحديثات غير العاجلة وassertive بحذر وأتجنب الإعلانات المتكررة.', ['a11y']),
    q('What makes a custom keyboard widget accessible?', 'ما الذي يجعل custom keyboard widget accessible؟', 'It needs the correct role, accessible name, state, focus model, and keyboard pattern defined by the platform convention. I prefer native controls; for composite widgets I implement roving tabindex or aria-activedescendant and test with keyboard and screen readers.', 'يحتاج role صحيحًا واسمًا وحالة ونموذج focus ونمط keyboard متعارفًا عليه. أفضل العناصر الأصلية؛ وفي widgets المركبة أطبق roving tabindex أو aria-activedescendant وأختبر فعليًا.', ['a11y']),
    q('What is progressive enhancement in a modern SPA?', 'ما معنى progressive enhancement داخل SPA حديث؟', 'Core content and actions should remain understandable with resilient HTML and server behavior, then JavaScript enhances speed and interaction. The exact baseline depends on product needs, but failures should degrade intentionally rather than leave a blank shell.', 'يجب أن يبقى المحتوى والفعل الأساسي مفهومًا عبر HTML وserver behavior قويين، ثم تضيف JavaScript السرعة والتفاعل. مستوى الأساس حسب المنتج، لكن الفشل يجب أن يتدهور بشكل مقصود لا أن يترك صفحة فارغة.', ['html', 'perf']),
    q('How do native popover and dialog differ?', 'ما الفرق بين native popover وdialog؟', 'Popover handles nonmodal top-layer UI with light-dismiss behavior; dialog models a dialog and can be modal through <code>showModal()</code>. I choose by interaction semantics, then verify focus, naming, dismissal, and browser support.', 'Popover مناسب لواجهة nonmodal في top layer مع light-dismiss، أما dialog فيمثل نافذة ويمكن جعله modal عبر <code>showModal()</code>. أختار حسب semantics ثم أراجع focus والاسم والإغلاق والدعم.', ['html', 'a11y']),
    q('What are declarative shadow DOM and slots for?', 'فيم تستخدم declarative shadow DOM وslots؟', 'Declarative shadow DOM lets a server deliver a shadow tree in HTML, which can help SSR for Web Components. Slots project light-DOM content. I use shadow boundaries deliberately because styling, events, forms, and accessibility still need design.', 'يسمح declarative shadow DOM للسيرفر بإرسال shadow tree داخل HTML ويفيد SSR للـWeb Components. تمرر slots محتوى light DOM. أستخدم الحدود بحذر لأن styling وevents وforms وaccessibility تحتاج تصميمًا.', ['html']),
    q('How do you prevent duplicate IDs in component-driven UIs?', 'كيف تمنع duplicate IDs في واجهات مبنية من components؟', 'Reusable components generate stable instance-specific IDs and connect labels, help text, and errors with those IDs. I do not derive them from array indexes when reordering could change identity.', 'تولد الـcomponents IDs ثابتة وفريدة لكل instance وتربط بها labels وhelp text وerrors. لا أشتقها من index إذا كان الترتيب قد يتغير.', ['html', 'a11y']),
    q('What is the difference between hidden, inert, aria-hidden, and visually hidden?', 'ما الفرق بين hidden وinert وaria-hidden وvisually hidden؟', '<code>hidden</code> removes rendering, <code>inert</code> blocks interaction and focus in a subtree, <code>aria-hidden</code> hides from the accessibility tree but not visually, and visually-hidden CSS keeps content available to assistive technology. Using the wrong one can create focusable but unannounced controls.', '<code>hidden</code> يمنع العرض، و<code>inert</code> يمنع التفاعل وfocus داخل subtree، و<code>aria-hidden</code> يخفي من accessibility tree فقط، وvisually-hidden يبقي المحتوى لقارئ الشاشة. الاختيار الخاطئ قد يصنع control قابلًا للتركيز بلا إعلان.', ['html', 'a11y']),
  ],
  'topic-2': [
    q('How do lexical environments differ from the call stack?', 'ما الفرق بين lexical environments والـcall stack؟', 'The call stack tracks active execution contexts; lexical environments hold identifier bindings and outer references used for scope resolution. A closure can keep an environment reachable after its creating call has left the stack.', 'الـcall stack يتابع execution contexts النشطة، بينما lexical environments تحفظ bindings وروابط النطاق الخارجي. قد تُبقي closure البيئة موجودة بعد خروج الاستدعاء من stack.', ['js']),
    q('How do property descriptors affect object behavior?', 'كيف تؤثر property descriptors على سلوك الـobject؟', 'Data properties have value and writable; all properties have enumerable and configurable. Accessor properties use get/set. Descriptor defaults in <code>defineProperty</code> are false, which can surprise code relying on enumeration or reassignment.', 'خصائص البيانات لها value وwritable، وكل الخصائص لها enumerable وconfigurable، وaccessor تستخدم get/set. القيم الافتراضية في <code>defineProperty</code> تكون false وقد تفاجئ كود enumeration أو التعديل.', ['js']),
    q('What is the difference between equality, identity, and SameValueZero?', 'ما الفرق بين equality وidentity وSameValueZero؟', '<code>===</code> avoids coercion but treats NaN as unequal and +0/-0 as equal. <code>Object.is</code> changes those two cases. Map, Set, and includes use SameValueZero, where NaN matches itself and signed zero is equal.', '<code>===</code> لا يقوم coercion لكنه يعتبر NaN غير مساوية لنفسها و+0/-0 متساويين. <code>Object.is</code> يعكس هاتين الحالتين. Map وSet وincludes تستخدم SameValueZero.', ['js']),
    q('When does structuredClone work, and what does it not preserve?', 'متى تعمل structuredClone وما الذي لا تحتفظ به؟', 'It deep-clones many structured values and supports transferable objects, cycles, Map, Set, and typed arrays. It does not clone functions or DOM nodes, and custom prototypes or property descriptors should not be assumed to survive as application semantics.', 'تنسخ كثيرًا من القيم بعمق وتدعم transferable objects والدورات وMap وSet وtyped arrays. لا تنسخ functions أو DOM nodes، ولا أعتمد عليها للحفاظ على custom prototypes أو descriptors كسلوك للتطبيق.', ['js']),
    q('How do iterators, iterables, and generators relate?', 'ما علاقة iterators وiterables وgenerators ببعضها؟', 'An iterable exposes <code>Symbol.iterator</code>; an iterator returns <code>{value, done}</code>. A generator function creates an object implementing both, suspending at <code>yield</code>. I use them for lazy sequences and protocol integration.', 'الـiterable يوفّر <code>Symbol.iterator</code> والـiterator يعيد <code>{value, done}</code>. generator ينشئ object يطبق الاثنين ويتوقف عند <code>yield</code>. أستخدمها للتسلسلات lazy والبروتوكولات.', ['js']),
    q('What are WeakMap and WeakSet actually good for?', 'فيم تستخدم WeakMap وWeakSet فعلًا؟', 'They hold object keys weakly, so membership does not keep those objects alive. They are useful for per-object metadata and cycle guards. They are intentionally non-enumerable, so they are not general caches with inspectable contents.', 'تحتفظ بمفاتيح objects بشكل weak فلا تمنع جمعها من الذاكرة. تفيد metadata لكل object ومنع الدورات. لا يمكن enumerate محتواها عمدًا، لذلك ليست cache عامة قابلة للفحص.', ['js']),
    q('How do AbortController and AbortSignal improve async design?', 'كيف يحسن AbortController وAbortSignal تصميم العمليات async؟', 'They provide a composable cancellation signal for fetch and other APIs. I pass the signal through layers, stop obsolete work, distinguish cancellation from failure, and still design server operations because aborting the client does not guarantee server rollback.', 'يوفران cancellation signal قابلًا للتمرير إلى fetch وغيرها. أمرر signal بين الطبقات وأوقف العمل القديم وأفرق cancellation عن failure، مع تذكر أن إلغاء العميل لا يضمن rollback على السيرفر.', ['js']),
    q('What is backpressure, and why can a frontend care?', 'ما هي backpressure ولماذا تهم الـfrontend؟', 'A producer can emit work faster than the consumer or UI can process it. I respond with batching, sampling, bounded queues, cancellation, virtualization, or flow control instead of allowing unbounded memory and stale work.', 'قد ينتج المصدر عملًا أسرع من قدرة المستهلك أو الواجهة. أعالج ذلك بالـbatching أوsampling أوqueues محدودة أوcancellation أوvirtualization بدل نمو الذاكرة والعمل القديم.', ['js', 'perf']),
    q('How do ESM live bindings differ from copied values?', 'كيف تختلف ESM live bindings عن القيم المنسوخة؟', 'An imported binding reflects updates made by the exporting module, but the importer cannot reassign that binding. Module evaluation is cached per realm, dependencies execute before dependents, and cycles require care around initialization order.', 'تعكس imported binding تحديثات الـmodule المصدر لكن لا يستطيع المستورد إعادة تعيينها. يتم cache للتقييم داخل realm، وتعمل dependencies قبل dependents، والدورات تحتاج حذرًا مع ترتيب initialization.', ['modules']),
    q('How would you investigate a JavaScript memory leak?', 'كيف تحقق في JavaScript memory leak؟', 'I reproduce a stable navigation or interaction loop, compare heap snapshots, inspect retained size and retainer paths, and look for detached DOM, listeners, timers, subscriptions, and unbounded caches. I verify the fix by repeating the same scenario and allowing GC.', 'أكرر سيناريو ثابتًا، وأقارن heap snapshots، وأفحص retained size وretainer paths، وأبحث عن detached DOM وlisteners وtimers وsubscriptions وcaches بلا حد، ثم أعيد القياس بعد السماح بـGC.', ['js', 'perf']),
  ],
  'topic-3': [
    q('How do mapped types transform an object type?', 'كيف تحول mapped types نوع object؟', 'A mapped type iterates over property keys and can change value types, optionality, readonly status, or remap keys. I use it to encode repeatable relationships, not to create unreadable type-level programs.', 'تدور mapped type على مفاتيح الخصائص ويمكنها تغيير النوع وoptional وreadonly أو إعادة تسمية المفاتيح. أستخدمها لعلاقات متكررة واضحة لا لبرامج type-level يصعب قراءتها.', ['tsTypes']),
    q('What are conditional types and distributivity?', 'ما هي conditional types وما معنى distributivity؟', 'A conditional type selects a type using <code>T extends U ? X : Y</code>. With a naked type parameter it distributes over unions; wrapping both sides in tuples suppresses distribution. I document that behavior because it is easy to misread.', 'تختار conditional type نوعًا بصيغة <code>T extends U ? X : Y</code>. عندما يكون T parameter مباشرًا تتوزع على union، ووضع الطرفين داخل tuples يمنع ذلك. أوثّق السلوك لأنه سهل الالتباس.', ['tsTypes']),
    q('When is infer useful inside a conditional type?', 'متى تكون infer مفيدة داخل conditional type؟', '<code>infer</code> captures a type part while pattern-matching, such as a function return, promise value, or tuple element. I prefer standard utilities where available and keep custom inference types small and testable.', 'تلتقط <code>infer</code> جزءًا من النوع أثناء pattern matching مثل return type أوقيمة Promise أوعنصر tuple. أفضل utility types الجاهزة وأجعل الأنواع المخصصة صغيرة وقابلة للاختبار.', ['tsTypes']),
    q('What does satisfies provide that an annotation or assertion does not?', 'ماذا توفر satisfies مقارنة بالـannotation أوassertion؟', '<code>satisfies</code> checks compatibility while retaining the expression’s more specific inferred type. An annotation may widen the value; an assertion can silence a mismatch. I use satisfies for configuration objects and exhaustive maps.', 'تتحقق <code>satisfies</code> من التوافق مع الاحتفاظ بالنوع المحدد المستنتج. قد توسع annotation النوع، وقد تخفي assertion خطأ. أستخدم satisfies في config وmaps الشاملة.', ['ts']),
    q('Explain TypeScript structural typing and excess-property checks.', 'اشرح structural typing وexcess-property checks في TypeScript.', 'Compatibility is based mainly on members, not declared names. Fresh object literals receive an extra check for unexpected properties, while variables can be structurally assignable with additional fields. Runtime validation remains separate.', 'يعتمد التوافق أساسًا على الأعضاء لا أسماء الأنواع. object literal جديد يخضع لفحص properties الزائدة، بينما variable قد يكون متوافقًا رغم حقول إضافية. runtime validation موضوع منفصل.', ['ts']),
    q('What are variance and strictFunctionTypes?', 'ما معنى variance وstrictFunctionTypes؟', 'Variance describes how generic relationships follow their type arguments. Function parameter checking under strictFunctionTypes prevents unsafe substitutions in many callback positions. I rarely add explicit variance annotations because TypeScript infers them and they do not rewrite structural behavior.', 'تصف variance كيف تنتقل علاقات الأنواع عبر generic arguments. يمنع strictFunctionTypes استبدالات غير آمنة في كثير من callbacks. نادرًا ما أضيف annotations لأن TypeScript تستنتجها ولا تغير structural behavior.', ['ts']),
    q('How do template literal types help API design?', 'كيف تساعد template literal types في تصميم API؟', 'They compose string unions into constrained event names, paths, or property accessors. They improve autocomplete for finite conventions, but I avoid huge unions that slow the checker or pretend arbitrary external strings are validated.', 'تركّب string unions إلى event names أوpaths أوaccessors مقيدة. تحسن autocomplete للاتفاقات المحدودة، لكن أتجنب unions ضخمة أوادعاء التحقق من strings خارجية.', ['tsTypes']),
    q('When do branded types help in a structurally typed system?', 'متى تفيد branded types في نظام structural؟', 'A private or unique-symbol brand distinguishes values with the same runtime representation, such as UserId and OrderId. Construction must go through a validated boundary; the brand itself adds no runtime validation.', 'تميز brand خاصة أوunique symbol قيمًا لها نفس التمثيل مثل UserId وOrderId. يجب إنشاء القيمة بعد validation؛ الـbrand نفسها لا تضيف تحققًا وقت التشغيل.', ['ts']),
    q('How do noUncheckedIndexedAccess and exactOptionalPropertyTypes change safety?', 'كيف يغير noUncheckedIndexedAccess وexactOptionalPropertyTypes الأمان؟', '<code>noUncheckedIndexedAccess</code> adds undefined to unchecked index reads. <code>exactOptionalPropertyTypes</code> distinguishes an absent optional property from one explicitly set to undefined unless allowed. Both reveal assumptions that looser projects hide.', 'يضيف <code>noUncheckedIndexedAccess</code> احتمال undefined لقراءة index غير مؤكدة. ويميز <code>exactOptionalPropertyTypes</code> بين غياب property ووجودها بقيمة undefined. يكشفان افتراضات مخفية.', ['ts']),
    q('How do you keep complex TypeScript types maintainable and fast?', 'كيف تحافظ على complex TypeScript types قابلة للصيانة وسريعة؟', 'I name intermediate types, limit recursion and giant unions, prefer readable domain types, inspect compiler diagnostics when checking slows, and avoid encoding runtime business logic entirely in types. A simpler API often beats clever inference.', 'أسمي الأنواع الوسيطة وأحد recursion وunions الضخمة وأفضل domain types واضحة وأفحص compiler diagnostics عند البطء. لا أحول business logic كاملًا إلى types؛ API أبسط غالبًا أفضل.', ['ts']),
  ],
  'topic-4': [
    q('How do you recognize a God service in a frontend?', 'كيف تكتشف God service في frontend؟', 'A service that owns unrelated state, transport, formatting, navigation, and policy has too many reasons to change. I split around cohesive capabilities and stable interfaces, then keep orchestration explicit rather than replacing one giant class with many trivial wrappers.', 'الـservice التي تملك state وtransport وformatting وnavigation وسياسات غير مترابطة لها أسباب كثيرة للتغيير. أقسمها حول capabilities متماسكة وinterfaces ثابتة مع orchestration واضح.', ['patterns']),
    q('What is the difference between domain, application, and infrastructure logic?', 'ما الفرق بين domain وapplication وinfrastructure logic؟', 'Domain logic expresses business rules, application logic coordinates use cases, and infrastructure talks to HTTP, storage, and frameworks. The boundaries need not become a heavy architecture, but separating volatile IO from rules improves testing and migration.', 'تعبر domain logic عن قواعد العمل، وتنسق application logic حالات الاستخدام، وتتحدث infrastructure مع HTTP وstorage والframework. فصل IO المتغير عن القواعد يحسن الاختبار والنقل دون مبالغة معمارية.', ['patterns']),
    q('When is an Adapter useful around a third-party library?', 'متى يفيد Adapter حول مكتبة خارجية؟', 'An adapter translates the vendor API into an interface shaped for the application. It localizes version churn, makes behavior explicit, and simplifies testing. I add it when the boundary is meaningful, not around every one-line library call.', 'يترجم Adapter واجهة المكتبة إلى interface مناسبة للتطبيق، ويعزل تغير الإصدارات ويسهل الاختبار. أضيفه عند وجود boundary حقيقية لا حول كل استدعاء بسيط.', ['patterns']),
    q('How is Strategy different from a large conditional?', 'كيف يختلف Strategy عن conditional كبيرة؟', 'Strategy encapsulates interchangeable behavior behind one contract and lets composition select it. It is valuable when algorithms evolve independently or need testing; a short stable conditional is often clearer when variation is tiny.', 'تغلف Strategy سلوكيات قابلة للتبديل خلف contract واحد ويختارها composition. تفيد عندما تتطور الخوارزميات مستقلًا؛ أما conditional قصيرة وثابتة فقد تكون أوضح.', ['patterns']),
    q('What are the risks of a frontend Facade?', 'ما مخاطر Facade في frontend؟', 'A facade can simplify a feature boundary and hide state implementation, but a universal facade may become a God object, duplicate selectors, or obscure events. I keep it feature-scoped, intention-revealing, and thin enough that data flow stays debuggable.', 'قد تبسط Facade حدود feature وتخفي implementation، لكن facade عامة قد تصبح God object وتكرر selectors وتخفي الأحداث. أجعلها feature-scoped وبأسماء نوايا واضحة وتدفق قابل للتتبع.', ['patterns']),
    q('Where does the Command pattern appear in UI systems?', 'أين يظهر Command pattern في UI؟', 'A command represents an action as data or an object, enabling queues, retries, undo, logging, and authorization checks. State-management actions resemble commands/events, but I distinguish a requested action from a fact that already happened.', 'تمثل Command فعلًا كبيانات أوobject مما يتيح queue وretry وundo وlogging وفحص الصلاحية. قد تشبه state actions لكن أفرق بين طلب الفعل وحقيقة حدثت بالفعل.', ['patterns']),
    q('How would you design undo and redo?', 'كيف تصمم undo وredo؟', 'I choose between inverse commands and state snapshots based on operation cost and determinism. I bound history, group related edits, define behavior around remote changes, and avoid storing huge mutable object graphs.', 'أختار بين inverse commands وstate snapshots حسب التكلفة والحتمية. أحدد history، وأجمع التعديلات المرتبطة، وأحدد التعامل مع remote changes، ولا أخزن object graphs ضخمة mutable.', ['patterns']),
    q('What does dependency inversion look like without a DI framework?', 'كيف تطبق dependency inversion دون DI framework؟', 'High-level code accepts behavior through parameters, factories, or constructor interfaces rather than importing a concrete transport. A container automates wiring; it is not the principle itself.', 'يستقبل الكود عالي المستوى السلوك عبر parameters أوfactories أوconstructor interfaces بدل استيراد transport concrete. الـcontainer يسهل wiring لكنه ليس المبدأ نفسه.', ['patterns']),
    q('How do you keep abstractions from becoming speculative?', 'كيف تمنع abstractions من أن تصبح speculative؟', 'I extract an abstraction after seeing a stable shared reason to change, give it a narrow contract, and keep callers simple. I avoid generic repositories, factories, or base classes created only because another implementation might exist someday.', 'أستخرج abstraction بعد ظهور سبب تغيير مشترك وثابت، وأعطيها contract ضيقة. أتجنب repositories أوfactories أوbase classes عامة فقط لاحتمال implementation آخر مستقبلًا.', ['patterns']),
    q('How do you evaluate composition versus inheritance in UI code?', 'كيف تقيّم composition مقابل inheritance في UI؟', 'Composition combines behaviors and data explicitly and avoids fragile base-class coupling. Inheritance is reasonable for a true substitutable relationship with a stable contract, but component trees and directives usually favor composition.', 'تجمع composition السلوك والبيانات بوضوح وتتجنب coupling هش مع base class. inheritance مناسبة لعلاقة substitutable حقيقية وcontract ثابتة، لكن UI components غالبًا تستفيد من composition.', ['patterns']),
  ],
  'topic-5': [
    q('How do browser caching and CDN caching differ?', 'ما الفرق بين browser caching وCDN caching؟', 'Browser caches are private to a client; CDN caches are shared near users. Cache-Control directives, validators, Vary, authorization, and cache keys determine correctness. I version immutable assets and design HTML/API caching separately.', 'Browser cache خاصة بالعميل وCDN cache مشتركة قرب المستخدمين. تتحكم Cache-Control وvalidators وVary وauthorization وcache keys في الصحة. أستخدم versioning للأصول وأصمم caching للHTML والAPI منفصلًا.', ['http']),
    q('What is the difference between strong and weak ETags?', 'ما الفرق بين strong وweak ETags؟', 'A strong ETag represents byte-for-byte equivalence and supports range semantics; a weak validator represents semantic equivalence. Clients send validators in conditional requests so a server can reply 304 without resending the body.', 'يمثل strong ETag تطابق bytes ويدعم range semantics، بينما weak validator يمثل تكافؤًا semantic. يرسل العميل validator في conditional request وقد يعيد السيرفر 304 بلا body.', ['http']),
    q('How do HTTP/2 and HTTP/3 change frontend optimization?', 'كيف يغير HTTP/2 وHTTP/3 تحسينات الـfrontend؟', 'Multiplexing reduces the old need for domain sharding and concatenating everything. HTTP/3 runs over QUIC and improves connection behavior under loss and migration. Bundling still matters for compression, caching, parse cost, and request overhead.', 'يقلل multiplexing الحاجة القديمة لـdomain sharding ودمج كل الملفات. يعمل HTTP/3 فوق QUIC ويحسن الاتصال مع loss والتنقل. يظل bundling مهمًا للضغط والcache وparse cost والoverhead.', ['http', 'perf']),
    q('When would you use WebSocket, Server-Sent Events, or polling?', 'متى تستخدم WebSocket أوSSE أوpolling؟', 'WebSocket supports bidirectional low-latency messaging; SSE is simpler server-to-client text streaming with HTTP reconnection semantics; polling is widely compatible and can be sufficient for infrequent updates. I compare direction, frequency, infrastructure, ordering, and recovery.', 'يدعم WebSocket اتصالًا ثنائيًا منخفض التأخير، وSSE بثًا نصيًا من السيرفر للعميل مع reconnection، وpolling بسيطًا مناسبًا للتحديثات القليلة. أقارن الاتجاه والتكرار والبنية والترتيب والتعافي.', ['http']),
    q('How do retries create duplicate writes?', 'كيف تسبب retries عمليات كتابة مكررة؟', 'A timeout does not prove the server failed; retrying a non-idempotent operation can duplicate it. I use idempotency keys or idempotent resource design, retry only suitable failures with bounds and jitter, and surface uncertain outcomes.', 'الـtimeout لا يثبت فشل السيرفر، وإعادة non-idempotent operation قد تكررها. أستخدم idempotency key أوتصميمًا idempotent، وأعيد أخطاء مناسبة فقط بحدود وjitter وأوضح النتائج غير المؤكدة.', ['http']),
    q('What is optimistic concurrency control?', 'ما هي optimistic concurrency control؟', 'The client submits a version or validator such as If-Match; the server rejects stale writes instead of silently overwriting newer data. The UI then asks the user to merge, reload, or retry based on product rules.', 'يرسل العميل version أوvalidator مثل If-Match، ويرفض السيرفر الكتابة القديمة بدل overwrite صامت. تعرض الواجهة خيار merge أوreload أوretry حسب قواعد المنتج.', ['http']),
    q('How do CORS and the same-origin policy differ?', 'ما الفرق بين CORS وsame-origin policy؟', 'The same-origin policy restricts script access to cross-origin resources. CORS is a server-controlled opt-in that lets browsers expose selected responses. It is not authentication, and a server-to-server client is not protected by browser CORS enforcement.', 'تقيّد same-origin policy وصول scripts لمصادر cross-origin. CORS سماح يحدده السيرفر ليكشف المتصفح responses محددة. ليست authentication ولا تطبقها المتصفحات على server-to-server clients.', ['http', 'security']),
    q('How do you reason about a preflight request?', 'كيف تفكر في preflight request؟', 'The browser sends OPTIONS before certain cross-origin requests to ask which methods, headers, credentials, and origins are allowed. I inspect the actual request origin and requested headers, then fix server policy rather than adding random client headers.', 'يرسل المتصفح OPTIONS قبل طلبات cross-origin معينة ليسأل عن methods وheaders وcredentials وorigins المسموحة. أفحص origin والheaders المطلوبة وأصلح سياسة السيرفر بدل headers عشوائية في العميل.', ['http']),
    q('What is content negotiation, and why does Vary matter?', 'ما هو content negotiation ولماذا يهم Vary؟', 'Servers may select a representation using Accept, encoding, or language headers. Shared caches need <code>Vary</code> so variants do not leak across incompatible requests, but excessive Vary values can destroy cache efficiency.', 'قد يختار السيرفر representation عبر Accept أوencoding أوlanguage. تحتاج shared caches إلى <code>Vary</code> حتى لا تختلط variants، لكن قيم Vary كثيرة قد تدمر كفاءة cache.', ['http']),
    q('How do you solve a frontend performance regression using Git?', 'كيف تحل frontend performance regression باستخدام Git؟', 'I establish a reproducible metric and environment, find a known-good commit, then use <code>git bisect</code> with a reliable manual or automated check. After identifying the change, I verify causation with profiling rather than blaming the commit correlation alone.', 'أثبت metric وبيئة قابلة للتكرار وأحدد commit سليمة ثم أستخدم <code>git bisect</code> مع check موثوق. بعد العثور على التغيير أؤكد السبب بالprofiling لا بمجرد الارتباط.', ['perf']),
    q('What does a Content Security Policy protect, and what does it not?', 'ماذا تحمي Content Security Policy وما حدودها؟', 'Content Security Policy restricts where scripts and other resources may load or execute, reducing the impact of injection. I prefer nonce or hash-based strict policies, deploy report-only first, and still fix the underlying XSS because CSP is defense in depth.', 'تقيّد Content Security Policy مصادر وتنفيذ scripts والموارد فتقلل أثر injection. أفضل strict policy بالnonce أوhash وأبدأ report-only، مع إصلاح XSS نفسها لأن CSP دفاع إضافي وليست بديلًا.', ['securityHeaders']),
    q('What problem do Trusted Types solve?', 'ما المشكلة التي تحلها Trusted Types؟', 'Trusted Types can require dangerous DOM sinks such as innerHTML to receive values created by an approved policy. This concentrates sanitization and blocks accidental string injection, but the policy itself must not blindly trust input.', 'يمكن لـTrusted Types إجبار sinks خطرة مثل innerHTML على استقبال قيم من policy معتمدة. تجمع sanitization وتمنع string injection العرضية، لكن يجب ألا تثق policy في input بلا تحقق.', ['securityHeaders']),
    q('How does CSRF happen, and how is it mitigated?', 'كيف يحدث CSRF وكيف تمنعه؟', 'A browser can attach ambient credentials such as cookies to a forged cross-site request. Defenses include SameSite cookies, anti-CSRF tokens, origin checks, and avoiding state changes through safe methods. XSS can bypass many CSRF defenses.', 'قد يرفق المتصفح credentials مثل cookies بطلب مزور cross-site. تشمل الحماية SameSite وanti-CSRF token وفحص origin وعدم تغيير state بsafe methods. تستطيع XSS تجاوز كثير من وسائل CSRF.', ['security']),
    q('How do HttpOnly, Secure, and SameSite cookie attributes differ?', 'ما الفرق بين HttpOnly وSecure وSameSite في cookies؟', 'HttpOnly blocks JavaScript access, Secure restricts transport to HTTPS, and SameSite controls cross-site attachment. Path, Domain, lifetime, prefixes, and server-side session design also matter; no single attribute makes a session secure.', 'يمنع HttpOnly وصول JavaScript، ويقيد Secure النقل على HTTPS، ويتحكم SameSite في الإرسال cross-site. يهم أيضًا Path وDomain والعمر والprefixes وتصميم session على السيرفر؛ لا توجد attribute سحرية.', ['http', 'security']),
    q('How do you defend against clickjacking?', 'كيف تمنع clickjacking؟', 'The server restricts who may frame the page using CSP <code>frame-ancestors</code> and, for legacy support, X-Frame-Options. Sensitive actions also need clear confirmation and robust authorization; frontend frame-busting scripts are not a reliable control.', 'يقيد السيرفر من يستطيع وضع الصفحة داخل frame عبر CSP <code>frame-ancestors</code> وX-Frame-Options للدعم القديم. تحتاج الأفعال الحساسة تأكيدًا وصلاحيات؛ frame-busting scripts ليست حماية موثوقة.', ['securityHeaders']),
    q('How do you use postMessage safely?', 'كيف تستخدم postMessage بأمان؟', 'I send to an exact targetOrigin, validate event.origin and the sender relationship, validate the payload schema, and expose a narrow message protocol. Using <code>*</code> or trusting a message by shape alone can leak data or trigger actions.', 'أرسل إلى targetOrigin محددة وأتحقق من event.origin وعلاقة المصدر وschema للpayload وأصمم protocol ضيقة. استخدام <code>*</code> أوالثقة في شكل الرسالة فقط قد يسرب بيانات أوينفذ أفعالًا.', ['security']),
    q('What is prototype pollution in frontend JavaScript?', 'ما هي prototype pollution في JavaScript؟', 'Unsafe recursive merging or path assignment can write attacker-controlled properties such as __proto__ into shared prototypes. I validate keys, use safe libraries and patched versions, prefer allowlists, and avoid treating plain objects as untrusted dictionaries.', 'قد تكتب عمليات merge أوpath assignment غير الآمنة properties يتحكم بها مهاجم مثل __proto__ داخل prototypes مشتركة. أتحقق من المفاتيح وأستخدم مكتبات محدثة وallowlists ولا أتعامل مع object عادي كdictionary غير موثوقة.', ['security']),
    q('How do you reduce frontend dependency supply-chain risk?', 'كيف تقلل مخاطر supply chain في dependencies؟', 'I minimize dependencies, pin and lock reproducible versions, review provenance and maintenance, scan advisories, restrict install scripts in sensitive pipelines, protect publishing credentials, and update through tested small changes.', 'أقلل dependencies وأثبت versions عبر lockfile وأراجع provenance والصيانة وأفحص advisories وأقيد install scripts في pipelines الحساسة وأحمي publishing credentials وأحدّث بتغييرات صغيرة مختبرة.', ['security']),
    q('What does Subresource Integrity provide?', 'ماذا توفر Subresource Integrity؟', 'SRI lets a browser verify that a fetched script or stylesheet matches an expected cryptographic hash. It is useful for fixed third-party assets, requires compatible CORS behavior for cross-origin resources, and needs hash updates when the asset changes.', 'تسمح SRI للمتصفح بالتحقق أن script أوstylesheet يطابق hash متوقعة. تفيد مع assets خارجية ثابتة وتتطلب CORS مناسبًا للcross-origin ويجب تحديث hash عند تغير الملف.', ['securityHeaders']),
    q('Where should access and refresh tokens be stored?', 'أين يجب تخزين access وrefresh tokens؟', 'There is no universal answer: I start from the threat model. Long-lived session secrets are often safer in Secure HttpOnly SameSite cookies with CSRF defenses; keeping tokens in JavaScript-accessible storage increases XSS exposure. Rotation, expiry, revocation, and server validation remain essential.', 'لا توجد إجابة واحدة؛ أبدأ بالthreat model. غالبًا تكون session secrets طويلة العمر أكثر أمانًا داخل Secure HttpOnly SameSite cookies مع CSRF defenses، بينما التخزين الذي تقرؤه JavaScript يزيد أثر XSS. يظل rotation وexpiry وrevocation والتحقق على السيرفر ضروريًا.', ['security', 'http']),
  ],
  'topic-6': [
    q('How does modern Angular schedule change detection without Zone.js?', 'كيف يجدول Angular الحديث change detection بدون Zone.js؟', 'Zoneless Angular reacts to explicit notifications such as updating a template-read signal, AsyncPipe emissions, bound listeners, input updates, and markForCheck. Code that changes state outside these paths must notify Angular deliberately.', 'يعتمد Zoneless Angular على إشعارات واضحة مثل تحديث signal مستخدمة في template وAsyncPipe وlisteners وinputs وmarkForCheck. الكود خارج هذه المسارات يجب أن يخطر Angular صراحة.', ['angularRoadmap', 'angular']),
    q('What changes when OnPush becomes the default strategy?', 'ماذا يتغير عندما تصبح OnPush هي الاستراتيجية الافتراضية؟', 'Components should update through inputs, signals, events, AsyncPipe, or explicit notifications rather than broad eager checks. Mutating an object in place can still hide a change when no notification occurs, so state boundaries and identity remain important.', 'يجب أن تتحدث components عبر inputs وsignals وevents وAsyncPipe أوإشعارات صريحة بدل checks واسعة. mutation داخل object قد يخفي التغيير إذا لم يحدث notification، لذلك تظل identity وحدود state مهمة.', ['angularRoadmap']),
    q('When do you use signal, linkedSignal, resource, and httpResource?', 'متى تستخدم signal وlinkedSignal وresource وhttpResource؟', 'A signal owns synchronous state; linkedSignal derives writable state that resets with dependencies; resource coordinates async state; httpResource specializes reactive HTTP fetching. I choose the narrowest primitive and keep mutation and cancellation semantics explicit.', 'تملك signal state متزامنة، وتشتق linkedSignal state قابلة للكتابة يعاد ضبطها مع dependencies، وتنسق resource async state، ويتخصص httpResource في HTTP reactive. أختار أبسط primitive وأوضح mutation وcancellation.', ['angularRoadmap']),
    q('How do signal inputs, outputs, and model inputs affect component APIs?', 'كيف تؤثر signal inputs وoutputs وmodel inputs على component APIs؟', 'Signal inputs provide reactive readonly input state, outputs emit events, and model inputs support explicit two-way value contracts. I still design one-way ownership first and reserve two-way models for controls with a clear value abstraction.', 'توفر signal inputs حالة input reactive للقراءة، وتطلق outputs أحداثًا، وتدعم model inputs عقد two-way واضحة. أبدأ بملكية one-way وأحصر two-way في controls لها value abstraction واضحة.', ['angular']),
    q('What are viewChild and contentChild signal queries?', 'ما هي viewChild وcontentChild signal queries؟', 'They expose query results as signals that update as the view or projected content changes. View queries inspect the component template; content queries inspect projected content. I avoid using queries as a substitute for clear data flow.', 'تعرض نتائج query كsignals تتغير مع view أوprojected content. تفحص view queries template الخاصة بالcomponent، وتفحص content queries المحتوى المسقط. لا أستخدم queries بدل data flow واضحة.', ['angular']),
    q('How does Angular injection context constrain inject()?', 'كيف يقيّد Angular injection context استخدام inject()؟', '<code>inject()</code> works while Angular is creating a class, in field initializers, provider factories, and code run in an injection context. Calling it later in an arbitrary callback fails unless a captured Injector is used with runInInjectionContext.', 'تعمل <code>inject()</code> أثناء إنشاء class وفي field initializers وprovider factories وكود داخل injection context. تفشل داخل callback عشوائية لاحقًا إلا باستخدام Injector محفوظة مع runInInjectionContext.', ['angular']),
    q('What is EnvironmentInjector ownership and destruction?', 'ما معنى ملكية EnvironmentInjector وتدميرها؟', 'An EnvironmentInjector owns provider instances created in its scope and runs destruction hooks when destroyed. Dynamically created injectors and components need explicit lifecycle ownership; losing the reference without destroying them can retain services and resources.', 'تملك EnvironmentInjector provider instances في نطاقها وتشغل destruction hooks عند تدميرها. injectors وcomponents المنشأة ديناميكيًا تحتاج lifecycle واضحة؛ فقد المرجع دون destroy قد يحتفظ بموارد.', ['angular']),
    q('When would you create a custom Angular directive with hostDirectives?', 'متى تنشئ Angular directive مخصصة باستخدام hostDirectives؟', 'Host directives compose reusable host behavior, bindings, and providers into components or directives without inheritance. I use them for cohesive behaviors such as focus or analytics and expose only intentional inputs and outputs.', 'تجمع hostDirectives سلوك host وbindings وproviders قابلة لإعادة الاستخدام دون inheritance. أستخدمها لسلوك متماسك مثل focus أوanalytics وأكشف inputs وoutputs المقصودة فقط.', ['angular']),
    q('How do built-in control flow and track affect list performance?', 'كيف يؤثر built-in control flow وtrack على أداء القوائم؟', '<code>@for</code> uses the track expression to associate data identity with DOM views. Stable unique keys minimize DOM destruction and preserve local state; tracking by index is suitable only when identity truly follows position.', 'تستخدم <code>@for</code> تعبير track لربط هوية البيانات بالDOM views. مفاتيح فريدة وثابتة تقلل destruction وتحفظ local state؛ track بالindex مناسب فقط عندما تتبع الهوية الموضع فعلًا.', ['angular']),
    q('How would you profile an Angular component before optimizing it?', 'كيف تعمل profiling لـAngular component قبل تحسينها؟', 'I reproduce a user-visible slowdown, inspect Angular DevTools change-detection and signal information, use the browser performance panel for scripting/layout/paint, and compare before/after traces. Render counts alone do not prove impact.', 'أكرر البطء الظاهر للمستخدم وأفحص Angular DevTools وbrowser performance panel للscripting وlayout وpaint وأقارن traces قبل وبعد. عدد renders وحده لا يثبت التأثير.', ['angular', 'perf']),
  ],
  'topic-7': [
    q('How do functional route guards and resolvers use DI?', 'كيف تستخدم functional route guards وresolvers الـDI؟', 'They call <code>inject()</code> in the router-provided injection context and return sync values, Promises, Observables, or redirects as appropriate. I keep authorization authoritative on the server and guards focused on navigation UX.', 'تستخدم <code>inject()</code> داخل injection context للrouter وتعيد قيمًا أوPromises أوObservables أوredirects. تبقى authorization حقيقية على السيرفر وتخدم guards تجربة التنقل.', ['angular']),
    q('How do route-level providers affect service lifetime?', 'كيف تؤثر route-level providers على عمر الـservice؟', 'A route can create an EnvironmentInjector for its providers, sharing instances within that route subtree. The lifetime follows router ownership and reuse behavior, so custom reuse strategies and retained handles must be reviewed when state appears to survive navigation.', 'قد ينشئ route EnvironmentInjector لمزوداته ويشارك instances داخل subtree. يتبع العمر ملكية router وسلوك reuse، لذلك أراجع reuse strategies والhandles المحتفظ بها إذا استمرت state بعد navigation.', ['angular']),
    q('How do you choose CSR, SSR, prerendering, or route-level render modes?', 'كيف تختار CSR أوSSR أوprerendering أوroute-level render modes؟', 'I choose per route: static public pages can prerender, personalized crawlable pages may SSR, highly interactive private areas may CSR. I compare freshness, hosting, TTFB, caching, hydration cost, and operational complexity.', 'أختار لكل route: الصفحات العامة الثابتة قد تستخدم prerender، والمخصصة القابلة للفهرسة SSR، والمناطق الخاصة شديدة التفاعل CSR. أقارن freshness وhosting وTTFB وcache وhydration والتعقيد.', ['angularRoadmap', 'perf']),
    q('What does @defer load, and what should trigger it?', 'ماذا يحمّل @defer وما الـtrigger المناسب؟', '<code>@defer</code> can split standalone dependencies into a lazy chunk and render placeholder, loading, and error states. I select viewport, interaction, idle, or explicit triggers from UX needs and avoid deferring content critical to LCP or accessibility.', 'يمكن لـ<code>@defer</code> فصل standalone dependencies في chunk كسول مع placeholder وloading وerror. أختار viewport أوinteraction أوidle حسب UX ولا أؤجل محتوى مهمًا لـLCP أوaccessibility.', ['angular']),
    q('How do Signal Forms differ from Reactive Forms?', 'كيف تختلف Signal Forms عن Reactive Forms؟', 'Signal Forms model form state and schema rules through signals and are stable in Angular v22, with interoperability for progressive migration. Reactive Forms remain valid and Observable-centric. I choose based on project version, ecosystem, complexity, and migration cost.', 'تبني Signal Forms حالة النموذج وقواعد schema بالsignals وهي stable في Angular v22 مع interoperability للهجرة التدريجية. تظل Reactive Forms صالحة وتعتمد Observables. أختار حسب الإصدار والنظام والتعقيد وتكلفة النقل.', ['angularRoadmap']),
    q('How do you build accessible custom form controls?', 'كيف تبني custom form controls accessible؟', 'The control needs a real label, keyboard and focus behavior, value semantics, disabled/read-only handling, validation state, and error association. Angular integration does not replace native accessibility; I prefer wrapping native inputs when possible.', 'يحتاج control label حقيقية وسلوك keyboard وfocus ومعنى value وتعامل disabled/readonly وحالة validation وربط errors. تكامل Angular لا يعوض accessibility الأصلية؛ أفضل تغليف native inputs.', ['angular', 'a11y']),
    q('How do you prevent refresh-token request storms?', 'كيف تمنع request storm أثناء refresh token؟', 'I allow one refresh operation, share its result with queued eligible requests, avoid intercepting the refresh itself, bound retries, and force a clean logout on terminal failure. The backend must rotate and validate tokens securely.', 'أسمح بعملية refresh واحدة وأشارك نتيجتها مع الطلبات المنتظرة المناسبة وأمنع interceptor من اعتراض refresh نفسها وأحد retries وأنفذ logout واضحًا عند الفشل النهائي. السيرفر مسؤول عن الأمان.', ['angular', 'security']),
    q('Where should authorization rules live in an Angular application?', 'أين تعيش authorization rules في تطبيق Angular؟', 'The server enforces every protected operation. The frontend may centralize capability checks to hide or disable UI consistently and guards may improve navigation, but neither is a security boundary.', 'يفرض السيرفر كل عملية محمية. قد تجمع الواجهة capability checks لإظهار UI متسق وتستخدم guards لتحسين navigation، لكن أيًا منهما ليس security boundary.', ['angular', 'security']),
    q('How do you preserve unsaved form work across navigation?', 'كيف تحفظ تعديلات form غير المحفوظة أثناء navigation؟', 'I define what counts as dirty, warn with a canDeactivate flow for in-app navigation, persist drafts when product requirements justify it, and handle version conflicts. Browser unload prompts are limited and should not be the only protection.', 'أحدد معنى dirty وأحذر عبر canDeactivate داخل التطبيق وأحفظ drafts إذا احتاج المنتج وأتعامل مع version conflicts. browser unload prompts محدودة ولا يجب الاعتماد عليها وحدها.', ['angular']),
    q('How do you test a complex validation flow?', 'كيف تختبر validation flow معقدة؟', 'I test pure rules directly, integration between control state and visible accessible errors, async validator cancellation and races, submit gating, server-error mapping, and keyboard behavior. I avoid asserting framework internals.', 'أختبر القواعد النقية مباشرة، وربط control state بالerrors المرئية والمتاحة، وإلغاء async validators والسباقات، ومنع submit وربط server errors وسلوك keyboard، دون اختبار internals للframework.', ['angular', 'testing']),
  ],
  'topic-8': [
    q('What is the difference between unicast and multicast Observables?', 'ما الفرق بين unicast وmulticast Observables؟', 'A cold unicast source normally creates independent work per subscriber. Multicasting shares one source subscription through a Subject-like connector. I make sharing explicit because it changes execution, lifetime, caching, and error behavior.', 'ينشئ cold unicast عملًا مستقلًا لكل subscriber عادة. تشارك multicasting subscription واحدة عبر connector شبيه Subject. أوضح المشاركة لأنها تغير التنفيذ والعمر والcache والأخطاء.', ['rxjs']),
    q('What do share reset options control?', 'ما الذي تتحكم فيه reset options داخل share؟', '<code>share</code> can reset its connector on error, completion, or when the reference count reaches zero. The right policy depends on whether data is a live stream, restartable computation, or finite request; defaults should be understood rather than copied.', 'يمكن لـ<code>share</code> إعادة connector عند error أوcomplete أووصول ref count للصفر. السياسة تعتمد على stream حي أوحساب قابل للإعادة أوطلب finite؛ يجب فهم defaults.', ['rxjs']),
    q('How do schedulers affect RxJS execution?', 'كيف تؤثر schedulers على تنفيذ RxJS؟', 'Schedulers control when queued work executes and can change recursion, batching, and interaction with the event loop. I use them for a specific timing or testing need, not as a generic performance switch.', 'تتحكم schedulers في توقيت العمل وقد تغير recursion وbatching وعلاقتها بالevent loop. أستخدمها لحاجة timing أوtesting محددة، لا كمفتاح أداء عام.', ['rxjs']),
    q('When are higher-order streams preferable to nested subscriptions?', 'متى تكون higher-order streams أفضل من nested subscriptions؟', 'Flattening operators make concurrency, cancellation, ordering, error scope, and teardown part of one pipeline. Nested subscriptions hide those policies and often complicate cleanup, though a deliberately bounded imperative subscription can still be clear.', 'تجعل flattening operators التزامن والإلغاء والترتيب ونطاق الخطأ والcleanup جزءًا من pipeline واحدة. تخفي nested subscriptions هذه السياسات، رغم أن imperative subscription محدودة قد تكون واضحة أحيانًا.', ['rxjs']),
    q('How do you preserve an outer stream after an inner request fails?', 'كيف تحافظ على outer stream بعد فشل inner request؟', 'I place <code>catchError</code> inside the flattening operator when one request should recover without terminating the source interaction stream. Catching outside instead handles failure for the whole composed stream and may end future interactions.', 'أضع <code>catchError</code> داخل flattening operator عندما يجب أن يتعافى طلب واحد دون إنهاء stream التفاعل. وضعها بالخارج يعالج pipeline كلها وقد يمنع تفاعلات لاحقة.', ['rxjs']),
    q('What is the role of finalize?', 'ما دور finalize؟', '<code>finalize</code> runs when an Observable terminates through completion, error, or unsubscription. It is useful for cleanup or paired UI state, but I avoid using it to hide shared mutable state whose ordering is unclear.', 'تعمل <code>finalize</code> عند complete أوerror أوunsubscribe. تفيد cleanup أوحالة UI مرتبطة، لكن لا أستخدمها لإخفاء shared mutable state بترتيب غامض.', ['rxjs']),
    q('How do you model request state without multiple drifting booleans?', 'كيف تمثل request state دون booleans متعددة غير متسقة؟', 'I use a discriminated state such as idle, loading, success with data, or error with context. One state prevents impossible combinations like loading and success simultaneously and makes templates and tests exhaustive.', 'أستخدم discriminated state مثل idle وloading وsuccess مع data أوerror مع context. تمنع state واحدة حالات مستحيلة مثل loading وsuccess معًا وتجعل template والtests شاملة.', ['rxjs', 'ts']),
    q('When can combineLatest appear to do nothing?', 'متى يبدو combineLatest وكأنه لا يعمل؟', 'It waits until every input has emitted at least once. A never-emitting source, a filtered initial value, or a late subscription can block output. I seed only when a real domain initial value exists, not merely to force emission.', 'ينتظر emission واحدة من كل input. قد يمنعه source لا يصدر أوinitial value مفلترة أوlate subscription. أضيف seed فقط إذا كانت هناك قيمة ابتدائية حقيقية في domain.', ['rxjs']),
    q('How do you test RxJS time-dependent behavior?', 'كيف تختبر سلوك RxJS المعتمد على الزمن؟', 'I use a test scheduler or controlled fake time to express emissions and subscription windows, then assert cancellation and completion as well as values. Real timers make tests slow and flaky.', 'أستخدم test scheduler أوfake time متحكمًا به للتعبير عن emissions وsubscription windows، وأختبر cancellation وcompletion بجانب القيم. timers الحقيقية تجعل الاختبارات بطيئة ومتذبذبة.', ['rxjs']),
    q('How do you apply backpressure-like strategies in RxJS?', 'كيف تطبق استراتيجيات شبيهة بالbackpressure في RxJS؟', 'RxJS push streams do not provide universal backpressure, so I choose domain controls: debounce, throttle, sample, buffer, window, bounded concurrency, cancellation, or dropping. The operator must match what data may safely be delayed or lost.', 'لا توفر RxJS backpressure عامة، لذلك أختار حسب domain: debounce أوthrottle أوsample أوbuffer أوwindow أوconcurrency محدودة أوcancellation أوdrop. يجب أن يناسب operator البيانات التي يمكن تأخيرها أوفقدها.', ['rxjs']),
  ],
  'topic-9': [
    q('What makes a Signal computation glitch-free?', 'ما معنى أن Signal computation تكون glitch-free؟', 'Computed values are memoized and dependencies are tracked dynamically, so consumers observe a consistent derived value rather than every intermediate assignment. I keep derivation in computed and use effects for external side effects.', 'تكون computed memoized وتتعقب dependencies ديناميكيًا، فيرى المستهلك قيمة مشتقة متسقة بدل كل assignment وسيطة. أضع derivation في computed وأستخدم effects للside effects الخارجية.', ['angular']),
    q('When is untracked appropriate in Signal code?', 'متى يكون untracked مناسبًا في Signal code؟', '<code>untracked</code> reads a signal without making it a dependency. I use it for incidental context in an effect, not to suppress a dependency that should actually trigger recomputation.', 'تقرأ <code>untracked</code> signal دون تسجيلها dependency. أستخدمها لمعلومة جانبية داخل effect، لا لإخفاء dependency يجب أن تعيد الحساب.', ['angular']),
    q('How do effect cleanup and service lifetime interact?', 'كيف يتفاعل effect cleanup مع عمر الـservice؟', 'An effect is destroyed with its injection context unless manually managed. A root service effect can therefore live for the application lifetime and retain what it captures; I keep captures small and use cleanup for external subscriptions or resources.', 'تُدمر effect مع injection context إلا إذا أديرت يدويًا. effect داخل root service قد تعيش عمر التطبيق وتحتفظ بما تلتقطه؛ أقلل captures وأستخدم cleanup للموارد الخارجية.', ['angular']),
    q('What should and should not live in NgRx Store?', 'ما الذي يجب وما لا يجب وضعه في NgRx Store؟', 'I store shared durable domain state and workflow state that benefits from events and replayable transitions. Ephemeral DOM state, duplicated derived data, nonserializable resources, and every local form keystroke usually belong elsewhere.', 'أخزن shared durable domain state وworkflow state التي تستفيد من events وانتقالات قابلة للتتبع. DOM state المؤقتة والبيانات المشتقة المكررة والموارد غير القابلة للserialization وكل keystroke محلية غالبًا مكانها خارج Store.', ['ngrx']),
    q('How do entity adapters affect NgRx state design?', 'كيف تؤثر entity adapters على تصميم NgRx state؟', 'An entity adapter normalizes collections into ids and entities and provides immutable update helpers and selectors. It reduces boilerplate but does not decide ownership, ordering, pagination, optimistic metadata, or cache invalidation.', 'تطبّع entity adapter collections إلى ids وentities وتوفر update helpers وselectors immutable. تقلل boilerplate لكنها لا تقرر الملكية أوالترتيب أوpagination أوoptimistic metadata أوcache invalidation.', ['ngrx']),
    q('How do you choose a flattening operator inside an NgRx effect?', 'كيف تختار flattening operator داخل NgRx effect؟', 'The action semantics decide: switch for latest-only reads, concat for ordered writes, exhaust for ignoring duplicate triggers while busy, and merge for safe concurrency. I also define error recovery so the effect source does not die.', 'تحدد semantics للaction الاختيار: switch لأحدث read، وconcat لكتابات مرتبة، وexhaust لتجاهل triggers مكررة أثناء العمل، وmerge لتوازي آمن. أحدد error recovery حتى لا تنتهي effect.', ['ngrx', 'rxjs']),
    q('What are optimistic updates and rollback in NgRx?', 'ما هي optimistic updates وrollback في NgRx؟', 'The reducer applies an immediate local change, an effect sends the request, and success reconciles authoritative data while failure rolls back or marks conflict. I attach operation identity so overlapping requests do not revert the wrong state.', 'يطبق reducer تغييرًا محليًا فورًا وترسل effect الطلب، ثم يصالح success بيانات السيرفر ويعيد failure الحالة أويسجل conflict. أربط operation identity حتى لا يرجع طلب متداخل state خاطئة.', ['ngrx']),
    q('How do selector props and factory selectors affect memoization?', 'كيف تؤثر selector props وfactory selectors على memoization؟', 'Selectors memoize based on input identity and their selector instance. Creating a new selector repeatedly or passing unstable objects defeats reuse. I create parameterized selectors at stable ownership boundaries and measure recomputation.', 'تعمل memoization حسب identity للinputs وinstance للselector. إنشاء selector جديدة باستمرار أوتمرير objects غير ثابتة يهدر reuse. أنشئ parameterized selectors في حدود ملكية ثابتة وأقيس recomputation.', ['ngrx']),
    q('How do you debug an NgRx action loop?', 'كيف تكتشف NgRx action loop؟', 'I inspect DevTools action history and effects that emit actions also matched by themselves or each other. I narrow ofType filters, separate command and success events, avoid unconditional redispatch, and test the effect sequence.', 'أفحص action history في DevTools وeffects التي تطلق actions تطابق نفسها أوغيرها. أضيق ofType وأفصل command عنsuccess وأمنع redispatch غير المشروط وأختبر تسلسل effect.', ['ngrx']),
    q('How can Signals and NgRx interoperate without duplicate sources of truth?', 'كيف تتكامل Signals وNgRx دون sources of truth مكررة؟', 'The Store remains authoritative for shared domain state; components can consume selected state through signal interop and keep local UI signals nearby. Writes flow through one chosen boundary rather than synchronizing two independently mutable copies.', 'تبقى Store المصدر الحقيقي للdomain state المشتركة، ويمكن للcomponents استهلاك selected state عبر signal interop مع local UI signals. تمر الكتابات عبر boundary واحدة بدل مزامنة نسختين mutable.', ['ngrx', 'angular']),
  ],
  'topic-10': [
    q('Explain the critical rendering path.', 'اشرح critical rendering path.', 'The browser parses HTML into DOM, CSS into CSSOM, combines them for layout, then paints and composites. Blocking resources, large DOM/CSS, synchronous scripts, layout invalidation, and heavy paint can delay useful pixels; I profile the actual bottleneck.', 'يفسر المتصفح HTML إلى DOM وCSS إلى CSSOM ثم ينفذ layout وpaint وcomposite. قد تؤخر blocking resources وDOM/CSS ضخمة وscripts متزامنة وlayout invalidation وpaint ثقيل ظهور المحتوى؛ أقيس عنق الزجاجة.', ['perf']),
    q('What causes layout thrashing?', 'ما الذي يسبب layout thrashing؟', 'Alternating DOM writes with layout reads can force repeated synchronous style and layout calculations. I batch reads and writes, use observers where appropriate, reduce DOM work, and verify the improvement in a performance trace.', 'التبديل بين DOM writes وlayout reads قد يفرض حساب style وlayout متزامنًا مرات كثيرة. أجمع القراءات والكتابات وأستخدم observers وأقلل DOM وأتحقق بالtrace.', ['perf']),
    q('How do long tasks damage INP?', 'كيف تضر long tasks مقياس INP؟', 'A long main-thread task delays input handling or the next presentation. I split or yield noncritical work, reduce JavaScript and rendering cost, move suitable computation to a worker, and measure input delay, processing, and presentation delay separately.', 'تؤخر long task على main thread معالجة input أوالعرض التالي. أقسم العمل أوأعمل yield وأقلل JavaScript وrendering وأنقل الحساب المناسب إلى worker وأقيس أجزاء INP منفصلة.', ['perf']),
    q('When does code splitting hurt instead of help?', 'متى يضر code splitting بدل أن يفيد؟', 'Too many tiny chunks add request, scheduling, evaluation, and cache complexity; poorly chosen boundaries create waterfalls or duplicate dependencies. I split by navigation and expensive optional features, then inspect chunk graphs and real traces.', 'قد تضيف chunks صغيرة كثيرة overhead وscheduling وevaluation وتعقيد cache، وقد تسبب boundaries سيئة waterfalls أوdependencies مكررة. أقسم حسب navigation وfeatures اختيارية مكلفة وأفحص graphs وtraces.', ['perf']),
    q('What is the difference between lab and field performance data?', 'ما الفرق بين lab وfield performance data؟', 'Lab data is controlled and reproducible for diagnosis; field data reflects real devices, networks, caches, and user behavior over distributions. I use field data to prioritize and lab traces to reproduce and fix.', 'بيانات lab متحكم بها وقابلة للتكرار للتشخيص، وfield تعكس أجهزة وشبكات وcache وسلوك مستخدمين حقيقيين كتوزيعات. أستخدم field للأولوية وlab لإعادة المشكلة وإصلاحها.', ['perf']),
    q('How do you set a frontend performance budget?', 'كيف تضع performance budget للfrontend؟', 'I define user-centered targets and enforce measurable limits such as JavaScript, image weight, route chunks, or CWV thresholds in CI and monitoring. Budgets need owners and an exception process; a number without enforcement is documentation only.', 'أحدد أهدافًا مرتبطة بالمستخدم وحدودًا قابلة للقياس مثل JavaScript وimages وroute chunks أوCWV في CI وmonitoring. تحتاج budgets مالكًا وآلية exceptions؛ الرقم بلا تطبيق مجرد توثيق.', ['perf']),
    q('What causes hydration mismatches?', 'ما أسباب hydration mismatches؟', 'Server and client DOM can differ because of invalid HTML repaired by the parser, nondeterministic values, browser-only branches, direct DOM mutation, whitespace configuration, or third-party scripts. I make rendering deterministic and delay DOM-mutating integrations.', 'قد يختلف DOM بين السيرفر والعميل بسبب HTML غير صالح يصلحه parser أوقيم غير حتمية أوbrowser-only branches أوDOM mutation أوwhitespace config أوthird-party scripts. أجعل rendering حتميًا وأؤجل integrations المعدلة للDOM.', ['angular', 'perf']),
    q('What does incremental hydration trade off?', 'ما trade-offs الخاصة بـincremental hydration؟', 'It hydrates deferred regions on triggers and can reduce initial work while preserving server-rendered content and event replay. It adds boundary and trigger design, testing complexity, and potential delayed interactivity if priorities are wrong.', 'تقوم بhydration لمناطق مؤجلة حسب triggers وقد تقلل العمل الأولي مع حفظ server content وevent replay. تضيف تعقيد boundaries وtriggers والاختبار وقد تؤخر interactivity إذا كانت الأولويات خاطئة.', ['angularRoadmap', 'perf']),
    q('How do source maps affect production debugging and security?', 'كيف تؤثر source maps على debugging والأمان في production؟', 'They map minified errors to source and materially improve observability. I upload private maps to the error service or restrict public access according to risk, verify release identifiers, and avoid embedding secrets because source maps are not a secret-management boundary.', 'تربط الأخطاء minified بالمصدر وتحسن observability. أرفع maps خاصة لخدمة الأخطاء أوأقيد الوصول حسب المخاطر وأتحقق من release IDs ولا أضع secrets لأن source maps ليست حماية أسرار.', ['perf', 'security']),
    q('What should frontend observability capture?', 'ماذا يجب أن تلتقط frontend observability؟', 'I capture errors with release and source maps, route and interaction context, performance spans and Web Vitals, failed network metadata, and sampling that protects privacy. Logs, traces, and metrics need correlation and actionable ownership.', 'ألتقط errors مع release وsource maps وسياق route وinteraction وperformance spans وWeb Vitals وmetadata للطلبات الفاشلة مع sampling يحمي الخصوصية. تحتاج logs وtraces وmetrics إلى correlation وملكية واضحة.', ['perf']),
  ],
  'topic-11': [
    q('A page freezes with 10,000 rows. What is your investigation plan?', 'صفحة تتجمد مع 10,000 صف؛ ما خطة التحقيق؟', 'I record a trace and separate data, scripting, style/layout, paint, and memory costs. Likely tools include pagination or virtualization, stable identity, cheaper cells, batching, and moving pure computation off-thread, but the trace chooses the fix.', 'أسجل trace وأفصل تكلفة البيانات وscripting وstyle/layout وpaint والذاكرة. قد أستخدم pagination أوvirtualization وidentity ثابتة وخلايا أخف وbatching أوworker، لكن القياس يحدد الحل.', ['perf']),
    q('Users see stale data after editing in another tab. What would you design?', 'المستخدم يرى بيانات قديمة بعد التعديل في tab أخرى؛ ماذا تصمم؟', 'I define consistency requirements, then use focus revalidation, BroadcastChannel or storage events for local coordination, server push when justified, version validators, and conflict UX. I avoid silently overwriting unsaved local work.', 'أحدد متطلبات consistency ثم أستخدم revalidation عند focus أوBroadcastChannel أوstorage events أوserver push عند الحاجة وversion validators وconflict UX، ولا أكتب فوق عمل محلي غير محفوظ.', ['js', 'http']),
    q('A deployment breaks only a subset of users. How do you respond?', 'deployment عطّل جزءًا فقط من المستخدمين؛ كيف تتصرف؟', 'I segment by release, browser, route, region, cache, and feature flag, inspect errors and asset loading, then mitigate with rollback or flag. I check stale HTML referencing removed hashed assets and keep deploys backward-compatible during cache propagation.', 'أقسم حسب release وbrowser وroute وregion وcache وfeature flag وأفحص errors وتحميل assets ثم أعمل rollback أوflag. أراجع HTML قديمة تشير إلى hashed assets محذوفة وأحافظ على compatibility أثناء انتشار cache.', ['perf', 'http']),
    q('How do you review a large frontend pull request?', 'كيف تراجع frontend pull request كبيرة؟', 'I understand the user behavior and risk first, inspect architecture and data flow, then correctness, accessibility, security, performance, tests, and maintainability. I separate blocking defects from suggestions and ask for smaller PRs when review quality is compromised.', 'أفهم behavior والمخاطر أولًا ثم architecture وdata flow وبعدها correctness وaccessibility وsecurity وperformance والtests والصيانة. أفصل blocking defects عنsuggestions وأطلب PRs أصغر إذا تضررت جودة المراجعة.', ['testing']),
    q('How would you migrate a large Angular app incrementally?', 'كيف تنقل Angular app كبيرة تدريجيًا؟', 'I establish a supported version path, automated migrations, representative tests and telemetry, then move bounded features behind stable contracts. I avoid simultaneous framework, architecture, design-system, and state rewrites unless evidence demands them.', 'أحدد مسار إصدارات مدعومًا وmigrations آلية وtests وtelemetry ممثلة ثم أنقل features محددة خلف contracts ثابتة. أتجنب تغيير framework وarchitecture وdesign system وstate معًا بلا ضرورة.', ['angularRoadmap', 'testing']),
    q('How do you decide whether to add a dependency?', 'كيف تقرر إضافة dependency؟', 'I compare problem fit, maintenance, security, bundle and runtime cost, browser support, API stability, licensing, and exit cost against a small in-house solution. Popularity alone is not evidence, and custom code also has ownership cost.', 'أقارن ملاءمة المشكلة والصيانة والأمان وحجم bundle وكلفة runtime ودعم المتصفح وثبات API والترخيص وكلفة الخروج بحل داخلي صغير. الشهرة وحدها ليست دليلًا والكود الداخلي له تكلفة ملكية.', ['security', 'perf']),
    q('What belongs in a frontend CI pipeline?', 'ما الذي يجب أن يوجد في frontend CI pipeline؟', 'At minimum I run deterministic install, type checking, linting, unit and integration tests, production build, content/schema checks, and targeted browser tests. Mature pipelines add dependency scanning, accessibility and performance budgets, previews, and safe deployment gates.', 'أشغل deterministic install وtype checking وlinting وunit/integration tests وproduction build وcontent checks وbrowser tests محددة. قد أضيف dependency scanning وaccessibility وperformance budgets وpreview وdeployment gates.', ['testing', 'security']),
    q('How do feature flags fail in practice?', 'كيف تفشل feature flags عمليًا؟', 'Stale flags create combinatorial paths, client-only flags cannot enforce security, and inconsistent evaluation can split behavior unexpectedly. I define ownership, expiry, rollout and rollback, telemetry, server authority, and tests for both states.', 'تخلق flags القديمة مسارات كثيرة، ولا تفرض client-only flags أمانًا، وقد يقسم evaluation غير المتسق السلوك. أحدد owner وexpiry وrollout/rollback وtelemetry وسلطة السيرفر وأختبر الحالتين.', ['testing', 'security']),
    q('How do you handle an inaccessible design handed to engineering?', 'كيف تتعامل مع design غير accessible وصل للفريق؟', 'I identify the user impact and violated interaction requirement, offer a concrete accessible alternative preserving the product intent, involve design early, and document the decision. Accessibility is a product constraint, not a polish step after implementation.', 'أوضح أثر المشكلة ومتطلب التفاعل المخالف وأقترح بديلًا accessible يحفظ هدف المنتج وأشرك design مبكرًا وأوثق القرار. accessibility قيد منتج وليست polish بعد التنفيذ.', ['a11y']),
    q('How do you explain a technical trade-off to non-engineers?', 'كيف تشرح technical trade-off لغير المهندسين؟', 'I frame the user or business outcome, present two or three viable options with cost, risk, reversibility, and evidence, recommend one, and state what signal would make us revisit it. I avoid jargon and false certainty.', 'أربط القرار بنتيجة للمستخدم أوbusiness وأعرض خيارات قابلة للتنفيذ مع التكلفة والمخاطر وقابلية الرجوع والدليل وأوصي بواحد وأحدد متى نعيد القرار، دون jargon أوثقة زائفة.', ['patterns']),
  ],
};

let nextId = 109;
for (const [topicId, questions] of Object.entries(additions)) {
  const topic = track.topics.find((item) => item.id === topicId);
  assert(topic, `Unknown topic ${topicId}`);
  for (const question of questions) topic.questions.push({ id: `q-${nextId++}`, ...question });
}
assert.equal(nextId, 239, 'Expansion must add 130 questions.');
fs.writeFileSync(path, `${JSON.stringify(track, null, 2)}\n`);
console.log('Added 130 senior frontend questions.');
